ALTER TABLE public.profiles ADD COLUMN faculty_id text;
ALTER TABLE public.profiles ADD COLUMN faculty_subject text;
CREATE OR REPLACE FUNCTION public.grant_faculty_access(_email text, _faculty_id text, _subject text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE target uuid; BEGIN SELECT id INTO target FROM auth.users WHERE lower(email) = lower(trim(_email)); IF target IS NULL THEN RETURN false; END IF; IF EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = target AND role = 'admin') THEN RAISE EXCEPTION 'Admin accounts cannot be changed to faculty'; END IF; UPDATE public.profiles SET faculty_id = upper(trim(_faculty_id)), login_id = upper(trim(_faculty_id)), faculty_subject = _subject WHERE id = target; INSERT INTO public.user_roles(user_id,role) VALUES(target,'faculty') ON CONFLICT (user_id,role) DO NOTHING; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.grant_faculty_access(text,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.grant_faculty_access(text,text,text) TO service_role;
CREATE TABLE public.faculty_leave_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, faculty_id text NOT NULL, faculty_name text NOT NULL, from_date date NOT NULL, to_date date NOT NULL, reason text NOT NULL CHECK (length(trim(reason)) BETWEEN 10 AND 500), status text NOT NULL DEFAULT 'Pending' CHECK (status IN ('Pending','Approved','Rejected')), created_at timestamptz NOT NULL DEFAULT now(), CHECK (to_date >= from_date));
GRANT SELECT, INSERT, UPDATE ON public.faculty_leave_requests TO authenticated;
GRANT ALL ON public.faculty_leave_requests TO service_role;
ALTER TABLE public.faculty_leave_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY faculty_leave_read ON public.faculty_leave_requests FOR SELECT TO authenticated USING ((user_id = auth.uid() AND public.has_role(auth.uid(),'faculty')) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY faculty_leave_submit ON public.faculty_leave_requests FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND public.has_role(auth.uid(),'faculty') AND status = 'Pending' AND faculty_id = (SELECT p.faculty_id FROM public.profiles p WHERE p.id = auth.uid()));
CREATE POLICY faculty_leave_admin_review ON public.faculty_leave_requests FOR UPDATE TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.validate_faculty_leave() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP = 'INSERT' AND NEW.from_date < CURRENT_DATE THEN RAISE EXCEPTION 'Start date cannot be in the past'; END IF; IF TG_OP = 'UPDATE' AND (NEW.user_id,NEW.faculty_id,NEW.faculty_name,NEW.from_date,NEW.to_date,NEW.reason,NEW.created_at) IS DISTINCT FROM (OLD.user_id,OLD.faculty_id,OLD.faculty_name,OLD.from_date,OLD.to_date,OLD.reason,OLD.created_at) THEN RAISE EXCEPTION 'Only the decision can be changed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_faculty_leave BEFORE INSERT OR UPDATE ON public.faculty_leave_requests FOR EACH ROW EXECUTE FUNCTION public.validate_faculty_leave();